CREATE TABLE authority_proposals (
 proposal_id TEXT PRIMARY KEY,family_id TEXT NOT NULL,run_id TEXT NOT NULL,
 run_class TEXT NOT NULL CHECK(run_class='STATISTICAL_TRIAL'),
 binding_sha256 TEXT NOT NULL CHECK(length(binding_sha256)=64),
 binding_json TEXT NOT NULL CHECK(json_valid(binding_json)),
 producer_session_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,
 resource_policy_sha256 TEXT CHECK(resource_policy_sha256 IS NULL OR length(resource_policy_sha256)=64),
 UNIQUE(run_id,binding_sha256)
) STRICT;
CREATE TABLE authority_transitions (
 transition_id INTEGER PRIMARY KEY AUTOINCREMENT,
 proposal_id TEXT NOT NULL REFERENCES authority_proposals(proposal_id),
 from_state TEXT NOT NULL CHECK(from_state IN ('NONE','PROPOSED','PRECONDITIONS_PASS','HUMAN_OWNER_SIGNED')),
 to_state TEXT NOT NULL CHECK(to_state IN ('PROPOSED','PRECONDITIONS_PASS','HUMAN_OWNER_SIGNED','APPLIED')),
 daemon_recorded_at TEXT NOT NULL,daemon_ledger_sequence INTEGER NOT NULL,
 immutable_session_id TEXT NOT NULL,authenticated_peer_uid INTEGER NOT NULL,
 event_sha256 TEXT NOT NULL UNIQUE CHECK(length(event_sha256)=64),
 resource_policy_sha256 TEXT CHECK(resource_policy_sha256 IS NULL OR length(resource_policy_sha256)=64),
 UNIQUE(proposal_id,daemon_ledger_sequence)
) STRICT;
CREATE TABLE logical_trials (
 logical_trial_id TEXT PRIMARY KEY,
 grant_proposal_id TEXT NOT NULL REFERENCES authority_proposals(proposal_id),
 candidate_list_sha256 TEXT NOT NULL CHECK(length(candidate_list_sha256)=64),
 UNIQUE(grant_proposal_id)
) STRICT;
CREATE TABLE trial_attempts (
 attempt_id TEXT PRIMARY KEY,logical_trial_id TEXT NOT NULL REFERENCES logical_trials(logical_trial_id),
 attempt_ordinal INTEGER NOT NULL CHECK(attempt_ordinal>=1),
 state TEXT NOT NULL CHECK(state IN ('RUNNING','ATTEMPT_VOID','COMPLETED')),
 checkpoint_sha256 TEXT CHECK(checkpoint_sha256 IS NULL OR length(checkpoint_sha256)=64),
 UNIQUE(logical_trial_id,attempt_ordinal)
) STRICT;
CREATE TABLE owner_conditional_delegations (
 delegation_id TEXT PRIMARY KEY,owner_identity TEXT NOT NULL,
 owner_credential_scheme TEXT NOT NULL CHECK(owner_credential_scheme='ED25519'),
 unsigned_payload_json TEXT NOT NULL CHECK(json_valid(unsigned_payload_json)),
 owner_signature_b64 TEXT NOT NULL,owner_signature_sha256 TEXT NOT NULL CHECK(length(owner_signature_sha256)=64),
 owner_session_id TEXT NOT NULL,expires_at TEXT NOT NULL,
 scope_sha256 TEXT NOT NULL CHECK(length(scope_sha256)=64),
 state TEXT NOT NULL CHECK(state='ACTIVE'),
 resource_policy_sha256 TEXT NOT NULL CHECK(length(resource_policy_sha256)=64)
) STRICT;
CREATE TABLE delegation_redemptions (
 redemption_event_id TEXT PRIMARY KEY,
 delegation_id TEXT NOT NULL REFERENCES owner_conditional_delegations(delegation_id),
 child_proposal_id TEXT NOT NULL REFERENCES authority_proposals(proposal_id),
 preconditions_transition_id INTEGER NOT NULL REFERENCES authority_transitions(transition_id),
 human_owner_signed_transition_id INTEGER NOT NULL REFERENCES authority_transitions(transition_id),
 scope_sha256 TEXT NOT NULL CHECK(length(scope_sha256)=64),
 resource_policy_sha256 TEXT CHECK(resource_policy_sha256 IS NULL OR length(resource_policy_sha256)=64),
 UNIQUE(delegation_id,child_proposal_id)
) STRICT;
CREATE TABLE owner_delegation_revocations (
 revocation_event_id TEXT PRIMARY KEY,
 delegation_id TEXT NOT NULL REFERENCES owner_conditional_delegations(delegation_id),
 daemon_recorded_at TEXT NOT NULL,daemon_ledger_sequence INTEGER NOT NULL,
 authenticated_owner_uid INTEGER NOT NULL,UNIQUE(delegation_id)
) STRICT;
CREATE TABLE amendment_registrations (
 amendment_event_id TEXT PRIMARY KEY,
 amendment_id TEXT NOT NULL CHECK(amendment_id IN ('C','D','A','B')),
 amendment_sha256 TEXT NOT NULL CHECK(length(amendment_sha256)=64),
 registration_ordinal INTEGER NOT NULL CHECK(registration_ordinal BETWEEN 1 AND 4),
 authorization_mode TEXT NOT NULL CHECK(authorization_mode IN ('INTERACTIVE_OWNER_SIGN','PREAUTHORIZED_CONDITIONAL_DELEGATION')),
 delegation_id TEXT REFERENCES owner_conditional_delegations(delegation_id),
 daemon_recorded_at TEXT NOT NULL,daemon_ledger_sequence INTEGER NOT NULL UNIQUE,
 authenticated_owner_uid INTEGER,producer_session_id TEXT NOT NULL,owner_session_id TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state='APPLIED'),
 UNIQUE(amendment_id),UNIQUE(registration_ordinal),
 CHECK(producer_session_id<>owner_session_id),
 CHECK((authorization_mode='INTERACTIVE_OWNER_SIGN' AND delegation_id IS NULL AND authenticated_owner_uid IS NOT NULL)
    OR (authorization_mode='PREAUTHORIZED_CONDITIONAL_DELEGATION' AND delegation_id IS NOT NULL AND authenticated_owner_uid IS NULL))
) STRICT;

CREATE TRIGGER authority_transition_order BEFORE INSERT ON authority_transitions BEGIN
 SELECT CASE
  WHEN NEW.daemon_ledger_sequence<=coalesce((SELECT max(daemon_ledger_sequence) FROM authority_transitions WHERE proposal_id=NEW.proposal_id),-1) THEN RAISE(ABORT,'daemon ledger order is not append-only')
  WHEN NEW.to_state='PROPOSED' AND (NEW.from_state!='NONE' OR EXISTS(SELECT 1 FROM authority_transitions WHERE proposal_id=NEW.proposal_id)) THEN RAISE(ABORT,'illegal authority transition')
  WHEN NEW.to_state='PRECONDITIONS_PASS' AND (NEW.from_state!='PROPOSED' OR (SELECT to_state FROM authority_transitions WHERE proposal_id=NEW.proposal_id ORDER BY transition_id DESC LIMIT 1)!='PROPOSED') THEN RAISE(ABORT,'illegal authority transition')
  WHEN NEW.to_state='HUMAN_OWNER_SIGNED' AND (NEW.from_state!='PRECONDITIONS_PASS' OR (SELECT to_state FROM authority_transitions WHERE proposal_id=NEW.proposal_id ORDER BY transition_id DESC LIMIT 1)!='PRECONDITIONS_PASS') THEN RAISE(ABORT,'illegal authority transition')
  WHEN NEW.to_state='APPLIED' AND (NEW.from_state!='HUMAN_OWNER_SIGNED' OR (SELECT to_state FROM authority_transitions WHERE proposal_id=NEW.proposal_id ORDER BY transition_id DESC LIMIT 1)!='HUMAN_OWNER_SIGNED') THEN RAISE(ABORT,'illegal authority transition')
  WHEN NEW.resource_policy_sha256 IS NOT (SELECT resource_policy_sha256 FROM authority_proposals WHERE proposal_id=NEW.proposal_id) THEN RAISE(ABORT,'resource policy transition mismatch')
 END;
END;
CREATE UNIQUE INDEX one_preconditions_per_proposal ON authority_transitions(proposal_id) WHERE to_state='PRECONDITIONS_PASS';
CREATE UNIQUE INDEX one_owner_sign_per_proposal ON authority_transitions(proposal_id) WHERE to_state='HUMAN_OWNER_SIGNED';
CREATE UNIQUE INDEX one_applied_per_proposal ON authority_transitions(proposal_id) WHERE to_state='APPLIED';
CREATE TRIGGER amendment_order_and_identity BEFORE INSERT ON amendment_registrations BEGIN
 SELECT CASE
  WHEN NEW.daemon_ledger_sequence<=coalesce((SELECT max(daemon_ledger_sequence) FROM amendment_registrations),-1) THEN RAISE(ABORT,'amendment ledger order is not append-only')
  WHEN NEW.registration_ordinal!=coalesce((SELECT max(registration_ordinal)+1 FROM amendment_registrations),1) THEN RAISE(ABORT,'amendment order gap')
  WHEN NEW.registration_ordinal=1 AND NOT(NEW.amendment_id='C' AND NEW.amendment_sha256='5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83' AND NEW.authorization_mode='INTERACTIVE_OWNER_SIGN') THEN RAISE(ABORT,'exact direct-owner C required first')
  WHEN NEW.registration_ordinal=2 AND NOT(NEW.amendment_id='D' AND NEW.amendment_sha256='c419cbdc0bc26670d5c18b37f183a9cd3481b00680f0b10d3176e482ef1d5be4' AND NEW.authorization_mode='INTERACTIVE_OWNER_SIGN') THEN RAISE(ABORT,'exact direct-owner D required second')
  WHEN NEW.registration_ordinal=3 AND NOT(NEW.amendment_id='A' AND NEW.amendment_sha256='495ad47fed0210ba4b495bdd86aa28784a5e5594df1e2648b6e04de8aa1fa379' AND NEW.authorization_mode='PREAUTHORIZED_CONDITIONAL_DELEGATION') THEN RAISE(ABORT,'exact delegated A required third')
  WHEN NEW.registration_ordinal=4 AND NOT(NEW.amendment_id='B' AND NEW.amendment_sha256='fa85f7033226c497262418aa1c7bba0eddcb1a340febcf36a5643aa3bddc52bf' AND NEW.authorization_mode='PREAUTHORIZED_CONDITIONAL_DELEGATION') THEN RAISE(ABORT,'exact delegated B required fourth')
 END;
END;
CREATE TRIGGER delegation_requires_exact_cd BEFORE INSERT ON owner_conditional_delegations BEGIN
 SELECT CASE WHEN (SELECT group_concat(identity,'|') FROM (SELECT amendment_id||':'||amendment_sha256||':'||authorization_mode||':'||state AS identity FROM amendment_registrations ORDER BY registration_ordinal))!='C:5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83:INTERACTIVE_OWNER_SIGN:APPLIED|D:c419cbdc0bc26670d5c18b37f183a9cd3481b00680f0b10d3176e482ef1d5be4:INTERACTIVE_OWNER_SIGN:APPLIED' THEN RAISE(ABORT,'exact C and D required before root') END;
END;
CREATE TRIGGER redemption_resource_binding BEFORE INSERT ON delegation_redemptions BEGIN
 SELECT CASE
  WHEN NEW.scope_sha256!=(SELECT scope_sha256 FROM owner_conditional_delegations WHERE delegation_id=NEW.delegation_id) THEN RAISE(ABORT,'redemption scope mismatch')
  WHEN NEW.resource_policy_sha256 IS NOT (SELECT resource_policy_sha256 FROM authority_proposals WHERE proposal_id=NEW.child_proposal_id) THEN RAISE(ABORT,'redemption proposal resource mismatch')
  WHEN NEW.resource_policy_sha256 IS NOT NULL AND NEW.resource_policy_sha256!=(SELECT resource_policy_sha256 FROM owner_conditional_delegations WHERE delegation_id=NEW.delegation_id) THEN RAISE(ABORT,'redemption root resource mismatch')
 END;
END;

